/** Look up the toggle spec for an ENT-ID. Returns null if unknown. */
export function getEntityToggleSpec(entId: string): EntityToggleSpec | null {
  return ENTITY_TOGGLES[entId] ?? null;
}

/** Build the default toggle-value map for an ENT-ID (uniform → 0.0/1.0). */
export function defaultTogglesFor(entId: string): Record<string, number> {
  const spec = ENTITY_TOGGLES[entId];
  if (!spec) return {};
  const out: Record<string, number> = {};
  for (const feat of spec.features) {
    out[feat.uniform] = feat.defaultOn ? 1.0 : 0.0;
  }
  return out;
}
